<?php $ic = fn(string $n) => '<svg class="ic" aria-hidden="true" focusable="false"><use href="#i-' . $n . '"/></svg>';
$cat = function (string $a): array { return match (true) { str_starts_with($a, 'auth.') => ['auth', 'Acesso'], str_starts_with($a, 'user.') => ['user', 'Usuários'], str_starts_with($a, 'settings.') => ['settings', 'Configurações'], str_starts_with($a, 'cash.') => ['cash', 'Caixa'], default => ['tab', 'Comandas'] }; };
$bad = fn(string $a) => (bool)preg_match('/(fail|denied|locked|revok|negad|block)/i', $a); ?>
<div class="info-box"><?= $ic('alert') ?><span>Visível somente ao proprietário. Os totais por operador são <b>registros</b> de ações — não medem produtividade: uma mesa pode ser atendida por várias pessoas.</span></div>
<section class="card tbl-card"><div class="card-h"><h2>Por operador</h2></div><div class="tw"><table><thead><tr><th>Nome</th><th>Perfil</th><th>Último acesso</th><th class="r">Rodadas lançadas</th><th class="r">Recebimentos informados</th><th class="r">Recebimentos conferidos</th></tr></thead><tbody>
<?php foreach ($ops as $o): ?><tr><td><b><?= e($o['name']) ?></b></td><td><?= e(Auth::ROLES[$o['role']] ?? $o['role']) ?></td><td><?= $o['last_login_at'] ? e(date('d/m/Y H:i', strtotime($o['last_login_at']))) : '—' ?></td><td class="r"><?= (int)$o['rounds'] ?></td><td class="r"><?= (int)$o['reported'] ?></td><td class="r"><?= (int)$o['confirmed'] ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="fbar" role="search"><label class="grow">Buscar por evento ou usuário<span class="search" style="position:relative"><?= $ic('search') ?><input type="search" data-filter="#tbl-log" placeholder="Buscar por evento ou usuário" aria-label="Buscar por evento ou usuário"></span></label>
  <div class="fchips" role="group" aria-label="Filtrar por tipo"><button type="button" class="fchip on" data-chip="#tbl-log" data-val="">Todos</button><button type="button" class="fchip" data-chip="#tbl-log" data-val="auth">Acessos</button><button type="button" class="fchip" data-chip="#tbl-log" data-val="user">Usuários</button><button type="button" class="fchip" data-chip="#tbl-log" data-val="settings">Configurações</button><button type="button" class="fchip" data-chip="#tbl-log" data-val="cash">Caixa</button><button type="button" class="fchip" data-chip="#tbl-log" data-val="tab">Comandas</button></div></div>
<section class="card tbl-card"><div class="card-h"><h2>Registros de acesso e ações sensíveis</h2><p>Últimos <?= count($log) ?> registros.</p></div><div class="tw"><table id="tbl-log"><thead><tr><th>Data e hora</th><th>Usuário</th><th>Evento</th><th>Detalhe</th></tr></thead><tbody>
<?php foreach ($log as $l): [$k, $kl] = $cat((string)$l['action']); ?><tr data-state="<?= $k ?>"><td><?= e(date('d/m/Y H:i:s', strtotime($l['created_at']))) ?></td><td><?= e($l['user_name'] ?? '—') ?></td><td><span class="pill-st <?= $bad((string)$l['action']) ? 'bad' : 'mute' ?>"><?= e($kl) ?></span> <?= e($l['action']) ?></td><td><?= e($l['detail']) ?></td></tr><?php endforeach; ?>
<?php if (!$log): ?><tr><td colspan="4"><div class="empty"><?= $ic('history') ?><p>Nenhum registro.</p></div></td></tr><?php endif; ?></tbody></table></div></section>
